// 治理受领组合窄门：真实TaskRecord/Common Action与资金预留，S6签发/S5条款用typed接头。
#include "resident/domains/tasks/governance_task_admission.hpp"
#include <cassert>
#include <iostream>
using namespace hanmo::resident;
// 接头代表S6当前复核；S3仍核公共签发fact、执行人和本次来源revision。
struct Authority:GovernanceAuthorityRead {
    GovernanceAuthorityApproval approval;mutable Integer calls=0;
    Outcome<GovernanceAuthorityApproval> governance_authority_approval(const StableId& id)const override{return id==approval.authority_fact_id?Outcome<GovernanceAuthorityApproval>{true,approval,{}}:Outcome<GovernanceAuthorityApproval>{false,{},common_failure("UnknownGovernanceAuthority").error};}
    Outcome<GovernanceAuthorityApproval> governance_authority_for_acceptance(const StableId& id,const StableId& executor,Integer revision)const override{++calls;if(executor!=approval.executor_actor_id||revision!=4)return {false,{},common_failure("AuthorityChanged").error};return governance_authority_approval(id);}
    Outcome<GovernanceContinuityResult> governance_continuity(const StableId&,const StableId&)const override{return {false,{},common_failure("UnusedAdmissionContinuity").error};}
};
// 预留沿唯一任务active/ready绑定治理contract，绝不把新动作ID伪充长期预留。
struct Reservations:ReservationOwnerRead {
    const TaskState& tasks;const GovernanceTaskState& governance;
    Reservations(const TaskState& t,const GovernanceTaskState& g):tasks(t),governance(g){}
    bool reservation_exists(const ReservationRef& ref)const override{return ref.kind==ReservationRef::Kind::contract&&governance_reservation_exists(tasks,governance,ref.id);}
};
// 正常、过期、旧revision与初始不足都经过同一实际受领入口，不手填已成功Task。
int main(){
    auto catalog=std::make_shared<CommonCatalog>();catalog->items.insert("grain",{"grain",1,1});catalog->texts.insert("name.appease","安民");CommonState initial;initial.metadata.ruleset_id=dynamic_ruleset_id;initial.identity.tick=3;initial.identity.revision=4;initial.next_instance_id=10;ActorRecord actor;actor.id="worker";actor.alive=true;actor.available=true;actor.hp=100;initial.actors.insert(actor.id,actor);initial.wallets.insert("public",{"public",{Owner::Kind::organization,"org",{}},200,{}});initial.inventories.insert("granary",{"granary",{Owner::Kind::organization,"org",{}},100,0,{{"stock","grain",{},10,{Owner::Kind::organization,"org",{}}}}});CommonStore common(initial,catalog);assert(common.append_fact({"authority",governance_authority_fact_kind,"politics"}).ok);
    Authority authority;auto& a=authority.approval;a.authority_fact_id="authority";a.issuer_actor_id="official";a.office_id="office";a.grant_id="grant";a.organization_id="org";a.executor_actor_id="worker";a.jurisdiction_id="county";a.site_id="site";a.rule_id="appease";a.rule_version="1";a.rule_name_key="name.appease";a.relief_policy_id="city_relief";a.public_wallet_id="public";a.public_inventory_id="granary";a.grain_item_id="grain";a.continuity_policy_id="frozen";a.issued_tick=1;a.offer_expires_tick=9;a.work_ticks=6;a.completion_deadline_ticks=8;a.cash_limit=120;a.grain_limit=10;
    TaskState tasks;GovernanceTaskState governance;Reservations reservations(tasks,governance);common.bind_reservation_owners(&reservations);
    assert(preview_governance_acceptance(common,governance,authority,"worker","authority",4).ok&&common.state().next_instance_id==10&&tasks.tasks.empty()&&common.wallet("public")->reserved.empty());assert(!preview_governance_acceptance(common,governance,authority,"worker","authority",3).ok);a.offer_expires_tick=2;assert(!preview_governance_acceptance(common,governance,authority,"worker","authority",4).ok);a.offer_expires_tick=9;
    Integer reserves=0;GovernanceReserveResources reserve=[&](const TaskGovernanceRead& read,const GovernanceTaskAcceptance& accepted,const GovernanceAuthorityApproval& approval)->Outcome<PublicReliefTerms>{++reserves;auto source=read.governance_task_source(accepted.task_id);assert(source.ok&&source.value.acceptance.relief_terms_id.empty()&&source.value.task_status=="active"&&common.action_order().empty());PublicReliefTerms terms;terms.id="terms:"+accepted.task_id;terms.task_id=accepted.task_id;terms.contract_id=accepted.contract_id;terms.acceptance_fact_id=accepted.fact_id;terms.authority_source_fact_id=accepted.authority_source_fact_id;terms.jurisdiction_id=accepted.jurisdiction_id;terms.site_id=accepted.site_id;terms.organization_id=accepted.organization_id;terms.public_wallet_id=approval.public_wallet_id;terms.public_inventory_id=approval.public_inventory_id;terms.item_id=approval.grain_item_id;terms.reservation_id=accepted.contract_id;terms.total_cash=approval.cash_limit;terms.total_grain=approval.grain_limit;
        ReservationRef reservation{ReservationRef::Kind::contract,terms.reservation_id};ResourceRecipe recipe;recipe.operations={SetReservation{terms.public_wallet_id,reservation,terms.total_cash,false},ReserveLots{terms.public_inventory_id,terms.item_id,terms.total_grain,{{Owner::Kind::organization,terms.organization_id,{}}},reservation}};auto applied=common.apply_resources(recipe);if(!applied.ok)return {false,{},applied.error};return {true,terms,{}};};
    auto accepted=begin_governance_task(common,tasks,governance,*catalog,authority,"worker","authority",4,reserve);assert(accepted.ok&&reserves==1&&accepted.value.accepted_tick==3&&accepted.value.deadline_tick==11&&accepted.value.work_ticks==6);assert(common.action_order().size()==1&&tasks.tasks.size()==1&&common.actor("worker")->action_id==common.action_order().front());const auto* action=common.action(common.action_order().front());assert(action->start_tick==3&&action->remaining_ticks==6&&action->kind=="governance_appease");assert(common.wallet("public")->balance==200&&common.wallet("public")->reserved.front().amount==120&&common.inventory("granary")->lots.front().quantity==10&&common.inventory("granary")->lots.front().reserved_by.kind==ReservationRef::Kind::contract);assert(validate_governance_tasks(common,tasks,governance).ok);
    const auto next=common.state().next_instance_id;assert(!begin_governance_task(common,tasks,governance,*catalog,authority,"worker","authority",4,reserve).ok&&reserves==1&&common.state().next_instance_id==next);
    // 不可先查全域已接受责任而绕过S6本人资格；陌生人猜中/未猜中ID只收到同一权源拒绝。
    ActorRecord stranger=actor;stranger.id="stranger";common.state().actors.insert(stranger.id,stranger);const auto before=encode_common_state(common.state());const auto calls=authority.calls;
    auto private_taken=preview_governance_acceptance(common,governance,authority,"stranger","authority",4);auto private_missing=preview_governance_acceptance(common,governance,authority,"stranger","missing",4);std::cerr<<"foreign existing/missing: "<<private_taken.error.original.code<<" / "<<private_missing.error.original.code<<'\n';assert(!private_taken.ok&&!private_missing.ok&&private_taken.error.original.code==private_missing.error.original.code&&authority.calls==calls+2);assert(compare_boundary(before,encode_common_state(common.state())).exact());
    // 承接初始资源不足时保留明确拒绝，不先开工；整个候选由外层丢弃。
    CommonStore insufficient(initial,catalog);assert(insufficient.append_fact({"authority",governance_authority_fact_kind,"politics"}).ok);insufficient.state().wallets.find("public")->balance=100;TaskState pending_tasks;GovernanceTaskState pending_governance;Reservations pending_reservations(pending_tasks,pending_governance);insufficient.bind_reservation_owners(&pending_reservations);
    auto failed=begin_governance_task(insufficient,pending_tasks,pending_governance,*catalog,authority,"worker","authority",4,[&](const TaskGovernanceRead&,const GovernanceTaskAcceptance& a,const GovernanceAuthorityApproval&)->Outcome<PublicReliefTerms>{auto spendable=insufficient.spendable("public");assert(spendable.ok&&spendable.value<120);return {false,{},common_failure("PublicReliefInsufficientFunds").error};});assert(!failed.ok&&insufficient.action_order().empty()&&insufficient.actor("worker")->action_id.empty()&&insufficient.wallet("public")->balance==100&&insufficient.wallet("public")->reserved.empty());
    // 固定安民成本不可用零额、少发或超额条款替代；规则未定义按支出比例缩放完整增益。
    for(const auto amounts:{std::pair<Integer,Integer>{0,0},{119,10},{120,9},{121,10}}){
        CommonStore wrong(initial,catalog);assert(wrong.append_fact({"authority",governance_authority_fact_kind,"politics"}).ok);TaskState wrong_tasks;GovernanceTaskState wrong_governance;
        auto result=begin_governance_task(wrong,wrong_tasks,wrong_governance,*catalog,authority,"worker","authority",4,[&](const TaskGovernanceRead&,const GovernanceTaskAcceptance& accepted,const GovernanceAuthorityApproval& approval)->Outcome<PublicReliefTerms>{PublicReliefTerms terms;terms.id="wrong.terms";terms.task_id=accepted.task_id;terms.contract_id=accepted.contract_id;terms.acceptance_fact_id=accepted.fact_id;terms.authority_source_fact_id=accepted.authority_source_fact_id;terms.jurisdiction_id=accepted.jurisdiction_id;terms.site_id=accepted.site_id;terms.organization_id=accepted.organization_id;terms.public_wallet_id=approval.public_wallet_id;terms.public_inventory_id=approval.public_inventory_id;terms.item_id=approval.grain_item_id;terms.reservation_id=accepted.contract_id;terms.total_cash=amounts.first;terms.total_grain=amounts.second;return {true,terms,{}};});
        assert(!result.ok&&result.error.original.code=="GovernanceReservationSourceMismatch"&&wrong.action_order().empty());
    }
    std::cout<<"governance_admission: pure current authority preview, exact agreed cash/grain costs, actual six-tick action after full reservation, absolute deadline, duplicate rejection and insufficient-funds no-start passed; S6/S5 typed test adapters only\n";
}
